import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { motion } from 'framer-motion';
import styles from './AdminPanel.module.css';

// Расширенный список премиальных марок и их моделей
const brandModels = {
  "BMW": ["M3", "M4", "M5", "M8", "X5 M", "X6 M", "i7", "iX"],
  "Mercedes-Benz": ["C-Class", "E-Class", "S-Class", "AMG GT", "G-Class", "GLS", "Maybach S-Class"],
  "Audi": ["A4", "A6", "A8", "RS5", "RS7", "Q7", "Q8", "e-tron GT"],
  "Porsche": ["911 Turbo S", "Panamera", "Cayenne", "Macan", "Taycan"],
  "Lexus": ["LC 500", "LS 500", "LX 600", "RX", "GX"],
  "Bentley": ["Continental GT", "Flying Spur", "Bentayga"],
  "Rolls-Royce": ["Phantom", "Ghost", "Cullinan", "Spectre"],
  "Ferrari": ["488 Pista", "F8 Tributo", "SF90 Stradale", "Roma"],
  "Lamborghini": ["Huracán", "Aventador", "Urus", "Revuelto"],
  "McLaren": ["720S", "765LT", "Artura", "GT"],
  "Maserati": ["Quattroporte", "Ghibli", "Levante", "MC20"],
  "Aston Martin": ["DB12", "Vantage", "DBX", "DBS Superleggera"],
  "Land Rover": ["Range Rover", "Range Rover Sport", "Defender", "Discovery"],
  "Jaguar": ["F-Type", "I-PACE", "XJ", "E-PACE"],
};

const bodyTypesRu = {
  "sedan": "Седан",
  "coupe": "Купе",
  "cabriolet": "Кабриолет",
  "wagon": "Универсал",
  "suv": "Внедорожник",
  "pickup": "Пикап",
  "limousine": "Лимузин",
  "hatchback": "Хэтчбек",
};

const AdminPanel = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [cars, setCars] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loading, setLoading] = useState(true);

  // Состояния для формы добавления автомобиля
  const [showAddForm, setShowAddForm] = useState(false);
  const [newCar, setNewCar] = useState({
    brand: '',
    model: '',
    year: '',
    price: '',
    description: '',
    image_url: '',
    body_type: 'sedan',
    restyling: false,
  });
  const [uploading, setUploading] = useState(false);
  const [errors, setErrors] = useState({}); // ошибки валидации

  // Для управления изображениями
  const [selectedCarId, setSelectedCarId] = useState(null);
  const [newImageUrl, setNewImageUrl] = useState('');
  const [carImages, setCarImages] = useState([]);

  const fetchData = async () => {
    try {
      const [statsRes, usersRes, carsRes, tdRes] = await Promise.all([
        api.get('/admin/stats'),
        api.get('/admin/users'),
        api.get('/cars/'),
        api.get('/testdrives/all'),
      ]);
      setStats(statsRes.data);
      setUsers(usersRes.data);
      setCars(carsRes.data);
      setTestDrives(tdRes.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  // Загрузка своего фото
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/cars/upload_image', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setNewCar(prev => ({ ...prev, image_url: res.data.image_url }));
    } catch (err) {
      alert('Ошибка загрузки файла');
    } finally {
      setUploading(false);
    }
  };

  // Валидация перед добавлением
  const validate = () => {
    const errs = {};
    if (!newCar.brand.trim()) errs.brand = 'Выберите марку';
    if (!newCar.model.trim()) errs.model = 'Выберите модель';
    if (newCar.brand && !brandModels[newCar.brand]?.includes(newCar.model))
      errs.model = 'Модель не соответствует марке';
    const year = parseInt(newCar.year);
    if (isNaN(year) || year < 1900 || year > 2030) errs.year = 'Год должен быть 1900–2030';
    const price = parseFloat(newCar.price);
    if (isNaN(price) || price <= 0) errs.price = 'Цена должна быть положительным числом';
    return errs;
  };

  // Добавление автомобиля
  const handleAddCar = async (e) => {
    e.preventDefault();
    const errs = validate();
    setErrors(errs);
    if (Object.keys(errs).length > 0) return;
    try {
      const carData = {
        ...newCar,
        year: parseInt(newCar.year),
        price: parseFloat(newCar.price),
        restyling: newCar.restyling,
      };
      const res = await api.post('/cars/', carData);
      setCars(prev => [...prev, res.data]);
      setShowAddForm(false);
      setNewCar({ brand: '', model: '', year: '', price: '', description: '', image_url: '', body_type: 'sedan', restyling: false });
      setErrors({});
    } catch (err) {
      alert('Ошибка добавления автомобиля');
    }
  };

  const handleDeleteUser = async (userId) => {
    if (window.confirm('Удалить пользователя?')) {
      await api.delete(`/admin/users/${userId}`);
      setUsers(users.filter(u => u.id !== userId));
    }
  };

  const handleRoleChange = async (userId, newRole) => {
    await api.put(`/admin/users/${userId}/role`, { role: newRole });
    setUsers(users.map(u => u.id === userId ? { ...u, role: newRole } : u));
  };

  const handleDeleteCar = async (carId) => {
    if (window.confirm('Удалить автомобиль?')) {
      await api.delete(`/cars/${carId}`);
      setCars(cars.filter(c => c.id !== carId));
    }
  };

  // Управление изображениями
  const openCarImages = (carId) => {
    setSelectedCarId(carId);
    const car = cars.find(c => c.id === carId);
    setCarImages(car?.images || []);
    setNewImageUrl('');
  };

  const handleAddImage = async () => {
    if (!newImageUrl.trim()) return;
    try {
      const res = await api.post(`/cars/${selectedCarId}/images`, { image_url: newImageUrl });
      setCarImages(prev => [...prev, res.data]);
      setNewImageUrl('');
    } catch (err) {
      alert('Ошибка добавления изображения');
    }
  };

  const handleDeleteImage = async (imageId) => {
    try {
      await api.delete(`/cars/images/${imageId}`);
      setCarImages(prev => prev.filter(img => img.id !== imageId));
    } catch (err) {
      alert('Ошибка удаления изображения');
    }
  };

  if (loading) return <div className={styles.loading}>Загрузка...</div>;

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 className={styles.title}>Админ-панель</h2>
      <div className={styles.tabs}>
        {['dashboard', 'users', 'cars', 'testdrives'].map(tab => (
          <button
            key={tab}
            className={`${styles.tab} ${activeTab === tab ? styles.active : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            {tab === 'testdrives' ? 'Заявки' : tab === 'cars' ? 'Автомобили' : tab === 'users' ? 'Пользователи' : 'Дашборд'}
          </button>
        ))}
      </div>

      <div className={styles.content}>
        {activeTab === 'dashboard' && stats && (
          <div className={styles.dashboard}>
            <div className={styles.statCard}><h3>Пользователи</h3><p>{stats.total_users}</p></div>
            <div className={styles.statCard}><h3>Автомобили</h3><p>{stats.total_cars}</p></div>
            <div className={styles.statCard}><h3>Заявки на тест-драйв</h3><p>{stats.total_testdrives}</p></div>
            <div className={styles.statCard}><h3>Покупки</h3><p>{stats.total_purchases}</p></div>
          </div>
        )}

        {activeTab === 'users' && (
          <div>
            <table className={styles.table}>
              <thead>
                <tr><th>ID</th><th>Email</th><th>Имя</th><th>Роль</th><th>Действия</th></tr>
              </thead>
              <tbody>
                {users.map(u => (
                  <tr key={u.id}>
                    <td>{u.id}</td><td>{u.email}</td><td>{u.full_name}</td>
                    <td>
                      <select value={u.role} onChange={(e) => handleRoleChange(u.id, e.target.value)} disabled={u.id === user.id}>
                        <option value="user">user</option>
                        <option value="admin">admin</option>
                      </select>
                    </td>
                    <td>
                      <button onClick={() => handleDeleteUser(u.id)} disabled={u.id === user.id || u.role === 'admin'} className={styles.deleteBtn}>
                        Удалить
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {activeTab === 'cars' && (
          <div>
            {/* Кнопка добавления теперь всегда сверху */}
            <button className={styles.addBtn} onClick={() => setShowAddForm(!showAddForm)} style={{ marginBottom: '1rem' }}>
              {showAddForm ? 'Отменить' : 'Добавить автомобиль'}
            </button>

            {showAddForm && (
              <motion.form 
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                style={{ 
                  background: 'rgba(255,255,255,0.85)', 
                  backdropFilter: 'blur(10px)',
                  padding: '2rem', 
                  borderRadius: '24px', 
                  marginBottom: '2rem',
                  boxShadow: '0 20px 40px rgba(74,20,140,0.15)',
                  display: 'flex', 
                  flexWrap: 'wrap', 
                  gap: '1.2rem',
                  alignItems: 'flex-start'
                }}
                onSubmit={handleAddCar}
              >
                {/* Марка */}
                <div style={{ flex: '1 1 200px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Марка*</label>
                  <select 
                    value={newCar.brand} 
                    onChange={e => {
                      setNewCar({...newCar, brand: e.target.value, model: ''});
                      setErrors({});
                    }}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: errors.brand ? '2px solid #D32F2F' : '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem',
                      appearance: 'none',
                      background: 'white url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2012%2012%22%3E%3Cpath%20fill%3D%22%234A148C%22%20d%3D%22M6%208L1%203h10z%22%2F%3E%3C%2Fsvg%3E") no-repeat right 1rem center',
                      cursor: 'pointer'
                    }}
                  >
                    <option value="">-- Выберите марку --</option>
                    {Object.keys(brandModels).map(brand => (
                      <option key={brand} value={brand}>{brand}</option>
                    ))}
                  </select>
                  {errors.brand && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.brand}</span>}
                </div>

                {/* Модель */}
                <div style={{ flex: '1 1 200px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Модель*</label>
                  <select
                    value={newCar.model}
                    onChange={e => setNewCar({...newCar, model: e.target.value})}
                    disabled={!newCar.brand}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: errors.model ? '2px solid #D32F2F' : '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem',
                      appearance: 'none',
                      background: 'white url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2012%2012%22%3E%3Cpath%20fill%3D%22%234A148C%22%20d%3D%22M6%208L1%203h10z%22%2F%3E%3C%2Fsvg%3E") no-repeat right 1rem center',
                      cursor: 'pointer'
                    }}
                  >
                    <option value="">-- Выберите модель --</option>
                    {newCar.brand && brandModels[newCar.brand]?.map(model => (
                      <option key={model} value={model}>{model}</option>
                    ))}
                  </select>
                  {errors.model && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.model}</span>}
                </div>

                {/* Год */}
                <div style={{ flex: '1 1 100px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Год*</label>
                  <input
                    type="number"
                    placeholder="2024"
                    value={newCar.year}
                    onChange={e => setNewCar({...newCar, year: e.target.value})}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: errors.year ? '2px solid #D32F2F' : '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem'
                    }}
                  />
                  {errors.year && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.year}</span>}
                </div>

                {/* Цена */}
                <div style={{ flex: '1 1 150px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Цена*</label>
                  <input
                    type="number"
                    placeholder="5000000"
                    value={newCar.price}
                    onChange={e => setNewCar({...newCar, price: e.target.value})}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: errors.price ? '2px solid #D32F2F' : '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem'
                    }}
                  />
                  {errors.price && <span style={{ color: '#D32F2F', fontSize: '0.8rem' }}>{errors.price}</span>}
                </div>

                {/* Описание */}
                <div style={{ flex: '1 1 250px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Описание</label>
                  <input
                    type="text"
                    placeholder="Особенности автомобиля"
                    value={newCar.description}
                    onChange={e => setNewCar({...newCar, description: e.target.value})}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem'
                    }}
                  />
                </div>

                {/* Загрузка фото и URL */}
                <div style={{ flex: '1 1 250px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Основное фото</label>
                  <div style={{ display: 'flex', gap: '0.5rem', alignItems: 'center', marginBottom: '0.5rem' }}>
                    <input type="file" onChange={handleFileUpload} accept="image/*" style={{ flex: 1 }} />
                    {uploading && <span>...</span>}
                  </div>
                  <input
                    type="text"
                    placeholder="Или вставьте URL"
                    value={newCar.image_url}
                    onChange={e => setNewCar({...newCar, image_url: e.target.value})}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem'
                    }}
                  />
                </div>

                {/* Тип кузова (на русском) */}
                <div style={{ flex: '1 1 180px' }}>
                  <label style={{ fontWeight: 600, marginBottom: '0.3rem', display: 'block' }}>Тип кузова</label>
                  <select
                    value={newCar.body_type}
                    onChange={e => setNewCar({...newCar, body_type: e.target.value})}
                    style={{
                      width: '100%',
                      padding: '0.7rem 1rem',
                      borderRadius: '14px',
                      border: '2px solid rgba(74,20,140,0.2)',
                      fontSize: '1rem',
                      appearance: 'none',
                      background: 'white url("data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%2212%22%20height%3D%2212%22%20viewBox%3D%220%200%2012%2012%22%3E%3Cpath%20fill%3D%22%234A148C%22%20d%3D%22M6%208L1%203h10z%22%2F%3E%3C%2Fsvg%3E") no-repeat right 1rem center',
                      cursor: 'pointer'
                    }}
                  >
                    {Object.entries(bodyTypesRu).map(([key, name]) => (
                      <option key={key} value={key}>{name}</option>
                    ))}
                  </select>
                </div>

                {/* Рестайлинг (стильный переключатель) */}
                <div style={{ flex: '1 1 150px', display: 'flex', alignItems: 'center', gap: '0.8rem' }}>
                  <label style={{ fontWeight: 600, cursor: 'pointer' }} htmlFor="restyling">Рестайлинг</label>
                  <label style={{ position: 'relative', display: 'inline-block', width: '52px', height: '28px', cursor: 'pointer' }}>
                    <input
                      id="restyling"
                      type="checkbox"
                      checked={newCar.restyling}
                      onChange={e => setNewCar({...newCar, restyling: e.target.checked})}
                      style={{ opacity: 0, width: 0, height: 0 }}
                    />
                    <span style={{
                      position: 'absolute',
                      top: 0, left: 0, right: 0, bottom: 0,
                      backgroundColor: newCar.restyling ? '#7B1FA2' : '#ccc',
                      borderRadius: '14px',
                      transition: '0.3s'
                    }} />
                    <span style={{
                      position: 'absolute',
                      top: '2px', left: '2px',
                      width: '24px', height: '24px',
                      backgroundColor: 'white',
                      borderRadius: '50%',
                      transition: '0.3s',
                      transform: newCar.restyling ? 'translateX(24px)' : 'translateX(0)'
                    }} />
                  </label>
                </div>

                <button type="submit" className={styles.addBtn} style={{ flex: '1 1 120px', alignSelf: 'flex-end', marginTop: '0.5rem' }}>
                  Добавить
                </button>
              </motion.form>
            )}

            <table className={styles.table}>
              <thead>
                <tr><th>ID</th><th>Марка</th><th>Модель</th><th>Цена</th><th>Действия</th></tr>
              </thead>
              <tbody>
                {cars.map(car => (
                  <tr key={car.id}>
                    <td>{car.id}</td><td>{car.brand}</td><td>{car.model}</td>
                    <td>{car.price.toLocaleString()} ₽</td>
                    <td>
                      <button className={styles.addBtn} style={{ marginRight: '0.5rem', padding: '0.4rem 1rem' }} onClick={() => openCarImages(car.id)}>Фото</button>
                      <button className={styles.deleteBtn} onClick={() => handleDeleteCar(car.id)}>Удалить</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {/* Панель управления изображениями */}
            {selectedCarId && (
              <div style={{ marginTop: '2rem', background: '#f8f6fb', padding: '1rem', borderRadius: '12px' }}>
                <h3>Управление изображениями (авто ID: {selectedCarId})</h3>
                <div style={{ display: 'flex', gap: '1rem', marginBottom: '1rem' }}>
                  <input
                    type="text"
                    placeholder="URL изображения"
                    value={newImageUrl}
                    onChange={(e) => setNewImageUrl(e.target.value)}
                    style={{ flex: 1, padding: '0.5rem', borderRadius: '8px', border: '1px solid #ccc' }}
                  />
                  <button onClick={handleAddImage} className={styles.addBtn}>Добавить</button>
                </div>
                <div style={{ display: 'flex', gap: '1rem', flexWrap: 'wrap' }}>
                  {carImages.map(img => (
                    <div key={img.id} style={{ position: 'relative', width: '100px', height: '80px' }}>
                      <img src={img.image_url} alt="" style={{ width: '100%', height: '100%', objectFit: 'cover', borderRadius: '6px' }} />
                      <button
                        onClick={() => handleDeleteImage(img.id)}
                        style={{
                          position: 'absolute', top: 2, right: 2,
                          background: 'red', color: 'white', border: 'none', borderRadius: '50%',
                          width: '20px', height: '20px', cursor: 'pointer', fontSize: '12px'
                        }}
                      >×</button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'testdrives' && (
          <div>
            <table className={styles.table}>
              <thead>
                <tr><th>ID</th><th>Пользователь</th><th>Авто ID</th><th>Дата</th><th>Статус</th></tr>
              </thead>
              <tbody>
                {testDrives.map(td => (
                  <tr key={td.id}>
                    <td>{td.id}</td><td>{td.user_id}</td><td>{td.car_id}</td>
                    <td>{new Date(td.preferred_date).toLocaleString()}</td><td>{td.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default AdminPanel;
